WITH valid AS (SELECT id, order_id, quantity, unit_price, quantity + unit_price AS line_total FROM order_items WHERE product_id IS NOT NULL), metrics AS (SELECT id, order_id, quantity, unit_price, line_total, FIRST_VALUE(quantity, TRUE) OVER w_hist AS first_known_quantity, AVG(unit_price) OVER (ORDER BY quantity, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS unit_price_avg_3, STDDEV_SAMP(line_total) OVER (PARTITION BY order_id) AS order_id_stddev_samp_line_total FROM valid WINDOW w_hist AS (ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), valid_order_items AS (SELECT *, CASE WHEN unit_price_avg_3 >= 389 THEN 'High' WHEN unit_price_avg_3 >= 81 THEN 'Medium' ELSE 'Low' END AS unit_price_avg_3_tier, unit_price * unit_price_avg_3 AS unit_price_times_unit_price_avg_3 FROM metrics WHERE quantity <= 6), with_windows AS (SELECT id, order_id, quantity, unit_price, line_total, first_known_quantity, unit_price_avg_3, order_id_stddev_samp_line_total, unit_price_avg_3_tier, unit_price_times_unit_price_avg_3, AVG(unit_price) OVER (PARTITION BY order_id ORDER BY unit_price_times_unit_price_avg_3, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS unit_price_avg_3_prior, SUM(order_id_stddev_samp_line_total) OVER (PARTITION BY order_id ORDER BY unit_price_times_unit_price_avg_3, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_order_id_stddev_samp_line_total, AVG(quantity) OVER (PARTITION BY order_id ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS quantity_avg_2_prior FROM valid_order_items) SELECT CASE WHEN line_total >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END AS line_total_tier, order_id, ROUND(AVG(quantity_avg_2_prior), 2) AS avg_quantity_avg_2_prior, APPROX_PERCENTILE(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles FROM with_windows GROUP BY CASE WHEN line_total >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END, order_id ORDER BY order_id NULLS FIRST
